const dir = mkdtempSync(path.join(tmpdir(), 'st-'));
process.env.STATE_DIR = dir;
const { decide, whyNotReceived, dryRun } = await import(BOT);
const u = { id: 'u1', timezone: 'Europe/Istanbul', consent: true }; // UTC+3
const d = (id, iso, user = u) => decide({ user, notification: { id }, now: new Date(iso) });
// quiet hours: 22:00 local = 19:00Z blocked, 08:00 local = 05:00Z allowed
assert.equal((await d('q1', '2026-10-20T18:59:00Z')).send, true);
assert.equal((await d('q2', '2026-10-20T19:00:00Z')).send, false);
assert.equal((await d('q3', '2026-10-21T04:59:00Z')).send, false);
assert.equal((await d('q4', '2026-10-21T05:00:00Z')).send, true);
