const r = [];
for (const [i, t] of ['06:00','07:00','08:00','09:00'].entries()) r.push((await d('c'+i, `2026-10-20T${t}:00Z`, v)).send);
assert.deepEqual(r, [true, true, true, false]);
// next local day resets (local date, not UTC): 20:50Z Oct 20 = 23:50 local quiet; use 05:00Z Oct 21
assert.equal((await d('c9', '2026-10-21T05:00:00Z', v)).send, true);
// no consent
assert.equal((await d('n1', '2026-10-20T10:00:00Z', { ...u, id: 'u3', consent: false })).send, false);
