assert.equal(w.length, 6 - 1); // c0..c3, c3 retry, c9 (c0 retry not recorded)
assert.equal(w[3].ruleCode, 'daily_cap');
assert.equal(w[3].availableAt, '2026-10-21T05:00:00.000Z');
const q = await whyNotReceived({ userId: 'u1', from: '2026-10-20T19:00:00Z', to: '2026-10-20T19:00:01Z' });
console.log(q[0]);
assert.equal(q[0].availableAt, '2026-10-21T05:00:00.000Z');
assert.equal((await whyNotReceived({ userId: 'u1', from: '2026-10-20T19:00:00Z', to: '2026-10-20T19:00:00Z' })).length, 0);
const nc = await whyNotReceived({ userId: 'u3', from: '2026-01-01T00:00:00Z', to: '2027-01-01T00:00:00Z' });
assert.equal(nc[0].ruleCode, 'no_consent'); assert.equal(nc[0].availableAt, null);
// dryRun: no state change
const before = JSON.stringify(readdirSync(dir + '/users').sort());
const ev = [];
for (let i = 0; i < 5; i++) ev.push({ user: { id: 'd1', timezone: 'UTC', consent: true }, notification: { id: 'e' + i }, at: `2026-10-20T${10 + i}:00:00Z` });
ev.push({ user: { id: 'd1', timezone: 'UTC', consent: true }, notification: { id: 'late' }, at: '2026-10-20T23:00:00Z' });
assert.deepEqual(await dryRun({ events: ev, policy: { quietHours: null, dailyCap: null } }), { delivered: 6, blocked: 0 });
assert.deepEqual(await dryRun({ events: ev, policy: { quietHours: null, dailyCap: 3 } }), { delivered: 3, blocked: 3 });
assert.deepEqual(await dryRun({ events: ev, policy: { quietHours: { start: '22:00', end: '08:00' }, dailyCap: 3 } }), { delivered: 3, blocked: 3 });
assert.deepEqual(await dryRun({ events: ev, policy: { quietHours: { start: '12:00', end: '14:00' }, dailyCap: 10 } }), { delivered: 4, blocked: 2 });
assert.equal(JSON.stringify(readdirSync(dir + '/users').sort()), before);
// DST: America/New_York fall back 2026-11-01; quiet end 08:00 EST = 13:00Z
const ny = { id: 'ny', timezone: 'America/New_York', consent: true };
await d('ny1', '2026-11-01T07:30:00Z', ny); // 02:30 EST (after fallback) -> quiet
const nyw = await whyNotReceived({ userId: 'ny', from: '2026-11-01T00:00:00Z', to: '2026-11-02T00:00:00Z' });
assert.equal(nyw[0].availableAt, '2026-11-01T13:00:00.000Z');
// concurrency: 8 processes x 10 decisions for one user, same local day => exactly 3 delivered
