for (let i = 0; i < 10; i++) { const r = await decide({ user: { id: 'race', timezone: 'UTC', consent: true }, notification: { id: id + '-' + i }, now: new Date('2026-10-20T12:00:00Z') }); if (r.send) n++; }
console.log(n);`;
import { writeFileSync } from 'node:fs';
writeFileSync('/tmp/gt/worker.mjs', worker);
