  const p = spawn('node', ['/tmp/gt/worker.mjs', 'w' + k], { env: process.env }); let o = '';
  p.stdout.on('data', c => o += c); p.stderr.on('data', c => process.stderr.write(c));
  p.on('close', c => c ? rej(new Error('worker fail')) : res(Number(o)));
})));
console.log('per-worker sends', outs);
assert.equal(outs.reduce((a, b) => a + b, 0), 3);
// restart: fresh process sees state
const out = execFileSync('node', ['-e', `import(${JSON.stringify(BOT)}).then(async m=>{const r=await m.decide({user:{id:'race',timezone:'UTC',consent:true},notification:{id:'after'},now:new Date('2026-10-20T13:00:00Z')});console.log(r.send)})`], { env: process.env }).toString().trim();
assert.equal(out, 'false');
console.log('ALL OK');
EOF
